/* o item n usa as porcentagens deslocadas em 4n%: um gerador escreve os 15 */

.ph { position:absolute; width:2px; background:var(--volt); animation: pkph 7.742s linear infinite, pkglow .484s ease-out infinite }
@keyframes pkph { from { left: 0 } to { left: calc(100% - 2px) } }
@keyframes pkglow { 0% { box-shadow: 0 0 10px rgba(180,242,19,.7) } 40%,100% { box-shadow: 0 0 6px rgba(180,242,19,.35) } }

.track i { transform-origin: 0 50%; animation: cgrow 8s cubic-bezier(.2,.8,.2,1) infinite }
@keyframes cgrow { 0%,36% { transform: scaleX(0) } 48%,94% { transform: scaleX(1) } 100% { transform: scaleX(0) } }
@keyframes cdim { 0%,54% { opacity: 1 } 60%,92% { opacity: .4 } 100% { opacity: 1 } }

.mh { animation: mh 3s linear infinite } @keyframes mh { to { transform: rotate(360deg) } }
.hh { animation: hh 18s linear infinite } @keyframes hh { from { transform: rotate(210deg) } to { transform: rotate(390deg) } }
.star { animation: star 18s linear infinite } @keyframes star { 0%,40% { opacity:0 } 55% { opacity:.8 } 70% { opacity:.35 } 82% { opacity:.9 } 100% { opacity:0 } }

.fc { transform-origin: 50% 130%; animation: fan 6s ease-in-out infinite }
.fc:nth-child(1) { --x: -60px; --r: -12deg } .fc:nth-child(3) { --x: 60px; --r: 12deg }
@keyframes fan { 0%,8% { transform:none } 30%,82% { transform: translateX(var(--x)) rotate(var(--r)) } 100% { transform:none } }
